from pathlib import Path
import hashlib, json, sys
output=Path(sys.argv[1]); raw_path=Path(sys.argv[2]); artifact=json.loads(output.read_text(encoding="utf-8")); raw=json.loads(raw_path.read_text(encoding="utf-8"))
requirements=artifact["artifacts"]["analytics_documentation"]["requirements"]; sources=artifact["artifacts"]["source_code_and_diff"]["sources"]; warnings=artifact["warnings"]; errors=[]
if [item["id"] for item in requirements] != [f"REQ-{n:04d}" for n in range(1,len(raw["order_change"]["facts"])+1)]: errors.append("canonical_requirement_ids")
for index,item in enumerate(requirements):
    if item["provenance"] != [f"/order_change/facts/{index}/id",f"/order_change/facts/{index}/quote"]: errors.append(f"requirement_{index}_identity_then_quote")
if f"/order_change/endpoint — {raw['order_change']['endpoint']}" not in sources: errors.append("endpoint_source_observation")
