if any(topic in " ".join(item["text"].lower() for item in requirements) for topic in ("authentication","authorization","retention","approval")): errors.append("invented_policy_requirement")
print(json.dumps({"artifact_sha256":hashlib.sha256(output.read_bytes()).hexdigest(),"semantic_errors":errors,"requirement_ids":[item["id"] for item in requirements],"source_count":len(sources),"warning_count":len(warnings)},sort_keys=True)); sys.exit(1 if errors else 0)
